import type { Metadata } from 'next';

// Next.js merges metadata shallowly, so a page that sets only title and
// description inherits the root layout's openGraph and twitter blocks whole,
// and every link preview shows the homepage. Every page builds its metadata
// here instead: its own social card, URL and canonical tag. Setting openGraph
// also drops the inherited file-based image, so it is named explicitly; it is
// generated by src/app/opengraph-image.tsx.
const OG_IMAGE = { url: '/opengraph-image', width: 1200, height: 630, alt: 'HireBuddha: Stop Hiring. Start Deploying.' };

export function buildMetadata({ title, description, path, absoluteTitle = false, type = 'website' }: {
  title: string;
  description: string;
  /** The page's path, e.g. "/pricing". Resolved against metadataBase. */
  path: string;
  /** Use the title as is, without the " · HireBuddha" template. */
  absoluteTitle?: boolean;
  type?: 'website' | 'article';
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} · HireBuddha`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: { type, siteName: 'HireBuddha', locale: 'en_IN', url: path, title: fullTitle, description, images: [OG_IMAGE] },
    twitter: { card: 'summary_large_image', title: fullTitle, description, images: [OG_IMAGE.url] },
  };
}
